## SECTION 2: PRODUCTION-READY C++ FIRMWARE FOR ESP32-S3

```cpp
/**
 * ========================================================================================
 * PROJECT:      PHONON-1 (The Acoustic Negawatt)
 * MODULE:       phonon1_firmware.ino / main.cpp
 * TARGET:       ESP32-S3 (Dual Core LX7, 240 MHz)
 * AUTHOR:       Student Hardware Hacker & Field Operations Lead
 * LICENSE:      MIT Open Hardware License / Phonon Dynamics Proprietary Field Release
 * DESCRIPTION:  Drives 1.70 - 2.40 MHz ultrasonic cavitation sweep, samples MAX6675
 *               thermocouple via SPI, tracks cavitation peak via ADC1, and streams
 *               telemetry to calculate real-time Negawatts.
 * ========================================================================================
 */

#include <Arduino.h>
#include <soc/soc.h>
#include <soc/rtc_cntl_reg.h>
#include <driver/ledc.h>
#include <esp_adc_cal.h>

#define PIN_PWM_OUT         4   // High-speed ultrasonic drive to Gate Driver (IN)
#define PIN_PWM_ENABLE      5   // Driver Shutdown / Enable (HIGH = Active)
#define PIN_TC_SCK          6   // MAX6675 SPI Clock
#define PIN_TC_CS           7   // MAX6675 SPI Chip Select (Active LOW)
#define PIN_TC_SO           8   // MAX6675 SPI Serial Data Out (MISO)
#define PIN_CAVITATION_ADC  9   // Piezo Cavitation Sensor Pickup (ADC1_CH8)
#define PIN_STATUS_LED      10  // Visual telemetry indicator (Resonance Lock / Error)

const uint32_t FREQ_MIN_HZ         = 1700000;  // 1.700 MHz lower bound
const uint32_t FREQ_MAX_HZ         = 2400000;  // 2.400 MHz upper bound
const uint32_t FREQ_SWEEP_STEP_HZ  = 5000;     // 5.0 kHz search step
const uint32_t TRACK_STEP_HZ       = 1500;     // 1.5 kHz gradient tracking step
const uint8_t  LEDC_CHANNEL        = LEDC_CHANNEL_0;
const uint8_t  LEDC_TIMER          = LEDC_TIMER_0;
const uint8_t  PWM_RESOLUTION_BITS = 4;        // 4-bit resolution allows up to 5 MHz carrier on ESP32-S3
const uint32_t PWM_DUTY_50PCT      = 8;        // 50% duty cycle square wave

const float COOLANT_FLOW_RATE_KG_S = 0.035f;   // 2.1 Liters/min typical server microchannel flow
const float SPECIFIC_HEAT_WATER    = 4184.0f;  // J / (kg * K)
const float THERMAL_RUNAWAY_LIMIT  = 90.0f;    // Automatic shutdown safety ceiling in °C

struct PhononSystemState {
    uint32_t current_freq_hz;
    uint32_t resonant_freq_hz;
    uint16_t cavitation_amplitude_raw;
    uint16_t max_cavitation_observed;
    float    coldplate_temp_c;
    float    baseline_temp_c;
    float    delta_temp_c;
    float    negawatts_reclaimed_w;
    bool     transducer_active;
    bool     resonance_locked;
    bool     thermocouple_fault;
} g_state;

TaskHandle_t TaskAcousticControlHandle = NULL;
TaskHandle_t TaskTelemetryHandle       = NULL;

void configureHardwarePWM(uint32_t frequency_hz) {
    ledc_timer_config_t ledc_timer = {
        .speed_mode       = LEDC_LOW_SPEED_MODE,
        .duty_resolution  = (ledc_timer_bit_t)PWM_RESOLUTION_BITS,
        .timer_num        = (ledc_timer_t)LEDC_TIMER,
        .freq_hz          = frequency_hz,
        .clk_cfg          = LEDC_USE_APB_CLK
    };
    ledc_timer_config(&ledc_timer);

    ledc_channel_config_t ledc_channel = {
        .gpio_num       = PIN_PWM_OUT,
        .speed_mode     = LEDC_LOW_SPEED_MODE,
        .channel        = (ledc_channel_t)LEDC_CHANNEL,
        .intr_type      = LEDC_INTR_DISABLE,
        .timer_sel      = (ledc_timer_t)LEDC_TIMER,
        .duty           = PWM_DUTY_50PCT,
        .hpoint         = 0
    };
    ledc_channel_config(&ledc_channel);
    g_state.current_freq_hz = frequency_hz;
}

void setHardwareFrequency(uint32_t frequency_hz) {
    ledc_set_freq(LEDC_LOW_SPEED_MODE, (ledc_timer_t)LEDC_TIMER, frequency_hz);
    ledc_set_duty(LEDC_LOW_SPEED_MODE, (ledc_channel_t)LEDC_CHANNEL, PWM_DUTY_50PCT);
    ledc_update_duty(LEDC_LOW_SPEED_MODE, (ledc_channel_t)LEDC_CHANNEL);
    g_state.current_freq_hz = frequency_hz;
}

float readMAX6675Temperature() {
    uint16_t raw_data = 0;
    digitalWrite(PIN_TC_CS, LOW);
    delayMicroseconds(2);
    for (int i = 15; i >= 0; i--) {
        digitalWrite(PIN_TC_SCK, HIGH);
        delayMicroseconds(1);
        if (digitalRead(PIN_TC_SO)) {
            raw_data |= (1 << i);
        }
        digitalWrite(PIN_TC_SCK, LOW);
        delayMicroseconds(1);
    }
    digitalWrite(PIN_TC_CS, HIGH);

    if (raw_data & 0x04) {
        g_state.thermocouple_fault = true;
        return -999.0f;
    }
    g_state.thermocouple_fault = false;
    uint16_t temp_bits = (raw_data >> 3) & 0x0FFF;
    return ((float)temp_bits) * 0.25f;
}

uint16_t sampleCavitationAmplitude() {
    uint16_t adc_min = 4095;
    uint16_t adc_max = 0;
    for (int i = 0; i < 64; i++) {
        uint16_t val = (uint16_t)analogRead(PIN_CAVITATION_ADC);
        if (val < adc_min) adc_min = val;
        if (val > adc_max) adc_max = val;
    }
    return (adc_max - adc_min);
}

void taskAcousticControl(void *pvParameters) {
    digitalWrite(PIN_PWM_ENABLE, HIGH);
    g_state.transducer_active = true;
    vTaskDelay(pdMS_TO_TICKS(100));

    uint32_t best_freq = FREQ_MIN_HZ;
    uint16_t max_pickup = 0;
    for (uint32_t f = FREQ_MIN_HZ; f <= FREQ_MAX_HZ; f += FREQ_SWEEP_STEP_HZ) {
        setHardwareFrequency(f);
        vTaskDelay(pdMS_TO_TICKS(4));
        uint16_t amp = sampleCavitationAmplitude();
        if (amp > max_pickup) {
            max_pickup = amp;
            best_freq = f;
        }
    }

    g_state.resonant_freq_hz        = best_freq;
    g_state.max_cavitation_observed = max_pickup;
    g_state.resonance_locked        = true;
    setHardwareFrequency(best_freq);

    int8_t search_direction = 1;
    while (true) {
        if (g_state.coldplate_temp_c > THERMAL_RUNAWAY_LIMIT) {
            digitalWrite(PIN_PWM_ENABLE, LOW);
            g_state.transducer_active = false;
            g_state.resonance_locked  = false;
            vTaskDelay(pdMS_TO_TICKS(5000));
            continue;
        }

        uint32_t next_freq = g_state.current_freq_hz + (search_direction * TRACK_STEP_HZ);
        if (next_freq > FREQ_MAX_HZ) {
            next_freq = FREQ_MAX_HZ;
            search_direction = -1;
        } else if (next_freq < FREQ_MIN_HZ) {
            next_freq = FREQ_MIN_HZ;
            search_direction = 1;
        }

        setHardwareFrequency(next_freq);
        vTaskDelay(pdMS_TO_TICKS(10));
        uint16_t new_amp = sampleCavitationAmplitude();
        g_state.cavitation_amplitude_raw = new_amp;

        if (new_amp < g_state.max_cavitation_observed * 0.92f) {
            search_direction = -search_direction;
        } else if (new_amp > g_state.max_cavitation_observed) {
            g_state.max_cavitation_observed = new_amp;
            g_state.resonant_freq_hz = next_freq;
        }

        digitalWrite(PIN_STATUS_LED, g_state.resonance_locked ? HIGH : !digitalRead(PIN_STATUS_LED));
        vTaskDelay(pdMS_TO_TICKS(20));
    }
}

void taskTelemetry(void *pvParameters) {
    uint32_t packet_counter = 0;
    while (true) {
        float current_temp = readMAX6675Temperature();
        if (current_temp > 0.0f) {
            g_state.coldplate_temp_c = (0.7f * g_state.coldplate_temp_c) + (0.3f * current_temp);
            g_state.delta_temp_c     = g_state.baseline_temp_c - g_state.coldplate_temp_c;
        }
        if (g_state.delta_temp_c > 0.0f) {
            g_state.negawatts_reclaimed_w = COOLANT_FLOW_RATE_KG_S * SPECIFIC_HEAT_WATER * g_state.delta_temp_c;
        } else {
            g_state.negawatts_reclaimed_w = 0.0f;
        }

        packet_counter++;
        Serial.printf("{\"seq\":%lu,\"millis\":%lu,\"freq_hz\":%lu,\"temp_c\":%.2f,\"base_temp_c\":%.2f,\"delta_temp_c\":%.2f,\"negawatts_w\":%.1f,\"cav_amp\":%u,\"locked\":%s,\"active\":%s}\n",
            packet_counter, millis(), g_state.current_freq_hz, g_state.coldplate_temp_c,
            g_state.baseline_temp_c, g_state.delta_temp_c, g_state.negawatts_reclaimed_w,
            g_state.cavitation_amplitude_raw, g_state.resonance_locked ? "true" : "false",
            g_state.transducer_active ? "true" : "false"
        );
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

void setup() {
    WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0);
    Serial.begin(115200);
    pinMode(PIN_PWM_ENABLE, OUTPUT);
    digitalWrite(PIN_PWM_ENABLE, LOW);
    pinMode(PIN_STATUS_LED, OUTPUT);
    digitalWrite(PIN_STATUS_LED, LOW);
    pinMode(PIN_TC_CS, OUTPUT);
    digitalWrite(PIN_TC_CS, HIGH);
    pinMode(PIN_TC_SCK, OUTPUT);
    digitalWrite(PIN_TC_SCK, LOW);
    pinMode(PIN_TC_SO, INPUT);
    pinMode(PIN_CAVITATION_ADC, INPUT);
    analogReadResolution(12);

    g_state.current_freq_hz = FREQ_MIN_HZ;
    g_state.resonant_freq_hz = 2000000;
    configureHardwarePWM(FREQ_MIN_HZ);

    xTaskCreatePinnedToCore(taskAcousticControl, "AcousticControlTask", 4096, NULL, configMAX_PRIORITIES - 1, &TaskAcousticControlHandle, 1);
    xTaskCreatePinnedToCore(taskTelemetry, "TelemetryTask", 4096, NULL, 2, &TaskTelemetryHandle, 0);
}

void loop() {
    vTaskDelay(pdMS_TO_TICKS(1000));
}
```

