        print(f"[{res['persona_name']}] Outrage: {res['outrage_level']}/100")
        print(f"  Verdict: \"{res['reaction']}\"")
        print(f"  Flagged Landmine: {res['fatal_flaw']}\n")

    avg_outrage = int(total_outrage / len(PERSONA_ROSTER))

